import re
import sys
import os
import logging
from datetime import datetime

def compute_expression(expr):
    try:
        return str(eval(expr))
    except ZeroDivisionError:
        return f"cannot compute {expr}"
    except Exception as e:
        return f"error evaluating {expr}: {str(e)}"

def process_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        return f"ERROR {file_path}: {str(e)}"

    def replacer(match):
        expr = match.group(1)
        result = compute_expression(expr)
        return result if result != f"cannot compute {expr}" else match.group(0)

    try:
        processed_content = re.sub(r'\{\{\s*([^}]+)\s*\}\}', replacer, content)
        with open(file_path, 'w', encoding='utf-8') as f:
            f.write(processed_content)
        return f"INFO processed {file_path}"
    except Exception as e:
        return f"ERROR {file_path}: {str(e)}"

