import sys
import re
import os
import logging
from datetime import datetime
from typing import List, Tuple

def evaluate_expression(expr: str) -> str:
    try:
        return str(eval(expr))
    except ZeroDivisionError:
        return f"cannot compute {expr}"
    except Exception as e:
        return f"error evaluating {expr}: {str(e)}"

def process_file(path: str) -> Tuple[bool, str]:
    try:
        with open(path, 'r', encoding='utf-8') as file:
            content = file.read()
    except Exception as e:
        return False, f"file read error: {str(e)}"

    def replace_placeholder(match):
        expr = match.group(1)
        result = evaluate_expression(expr)
        if isinstance(result, str) and result.startswith("cannot compute"):
            return match.group(0)
        return result

    try:
        updated_content = re.sub(r'\{\{(\w+|\d+[+\-*/%()\*\*]+)\}\}', replace_placeholder, content)
    except Exception as e:
        return False, f"placeholder replacement error: {str(e)}"

    try:
        with open(path, 'w', encoding='utf-8') as file:
            file.write(updated_content)
    except Exception as e:
        return False, f"file write error: {str(e)}"

    return True, ""

def main():
    log_file = "exprfill.log"
    logging.basicConfig(filename=log_file, level=logging.INFO, format='%Y-%m-%dT%H:%M:%S')

    for path in sys.stdin:
        path = path.strip()
        if not path:
            continue

        success, message = process_file(path)
        timestamp = datetime.now().strftime('%Y-%m-%dT%H:%M:%S')

        if success:
            logging.info(f"{timestamp} INFO processed {path}")
        else:
            logging.error(f"{timestamp} ERROR {path}: {message}")

if __name__ == "__main__":
    main()
